import { familyList, parseDimension, sameValue, shadowLayers, toHex, toMs } from '../values.mjs';

export const CSS_HEADER = `/*
 * GENERATED by design/ (npm run build) from design/tokens. Do not edit by hand.
 * Light values apply by default; dark values follow prefers-color-scheme and can be
 * forced with [data-theme='light'] or [data-theme='dark'] on the root element.
 */`;

/**
 * Formats the tokens of both modes as CSS custom properties.
 * @param {{ light: Array<object>, dark: Array<object> }} modes tokens named with name/kebab
 */
export function formatCss({ light, dark }) {
  const darkByName = new Map(dark.map((token) => [token.name, token]));
  const modal = light
    .map((token) => darkByName.get(token.name))
    .filter((token, i) => token && !sameValue(token.$value, light[i].$value));

  return [
    CSS_HEADER,
    '',
    block(":root,\n[data-theme='light']", 'light', light, ''),
    '',
    '@media (prefers-color-scheme: dark) {',
    block(":root:not([data-theme='light'])", 'dark', modal, '  '),
    '}',
    '',
    block("[data-theme='dark']", 'dark', modal, ''),
    '',
  ].join('\n');
}

function block(selector, scheme, tokens, indent) {
  const inner = `${indent}  `;
  const lines = [
    `${indent}${selector.split('\n').join(`\n${indent}`)} {`,
    `${inner}color-scheme: ${scheme};`,
  ];
  for (const token of tokens) {
    if (token.$description) {
      lines.push(`${inner}/* ${token.$description.replaceAll('*/', '* /')} */`);
    }
    lines.push(`${inner}--${token.name}: ${cssValue(token)};`);
  }
  lines.push(`${indent}}`);
  return lines.join('\n');
}

/** CSS value of a resolved token. */
export function cssValue(token) {
  const value = token.$value;
  switch (token.$type) {
    case 'color':
      return toHex(value);
    case 'dimension':
      // Radii keep px: shapes do not grow with the user's font size. The rest scales (rem).
      return token.path[0] === 'radius' ? px(value) : rem(value);
    case 'fontWeight':
    case 'number':
      return String(value);
    case 'fontFamily':
      return fontFamily(value);
    case 'duration':
      return `${toMs(value)}ms`;
    case 'cubicBezier':
      return `cubic-bezier(${value.join(', ')})`;
    case 'border':
      return `${px(value.width)} ${value.style ?? 'solid'} ${toHex(value.color)}`;
    case 'shadow':
      return shadowLayers(value)
        .map(
          (s) =>
            `${s.inset ? 'inset ' : ''}${px(s.offsetX)} ${px(s.offsetY)} ${px(s.blur)} ${px(s.spread ?? '0px')} ${toHex(s.color)}`,
        )
        .join(', ');
    case 'typography':
      return `${value.fontWeight} ${rem(value.fontSize)}/${value.lineHeight} ${fontFamily(value.fontFamily)}`;
    default:
      throw new Error(`Token "${token.path.join('.')}": type "${token.$type}" has no CSS format`);
  }
}

const GENERIC_FAMILIES = new Set([
  'serif',
  'sans-serif',
  'monospace',
  'cursive',
  'fantasy',
  'system-ui',
  'ui-serif',
  'ui-sans-serif',
  'ui-monospace',
  'ui-rounded',
  '-apple-system',
  'BlinkMacSystemFont',
]);

function fontFamily(value) {
  return familyList(value)
    .map((name) =>
      GENERIC_FAMILIES.has(name) || /^[A-Za-z][\w-]*$/.test(name) ? name : `'${name}'`,
    )
    .join(', ');
}

function px(raw) {
  const { value, unit } = parseDimension(raw);
  const pixels = unit === 'rem' ? value * 16 : value;
  return pixels === 0 ? '0' : `${round(pixels)}px`;
}

function rem(raw) {
  const { value, unit } = parseDimension(raw);
  const rems = unit === 'rem' ? value : value / 16;
  return rems === 0 ? '0' : `${round(rems)}rem`;
}

function round(n) {
  return Number(n.toFixed(4)).toString();
}
